    let attendanceLoadRequestId = 0;

    function attendanceParseDate(
      value
    ) {
      const match =
        String(value || "")
          .match(
            /^(\d{4})-(\d{2})-(\d{2})$/
          );

      if(!match) return null;

      return new Date(
        Date.UTC(
          Number(match[1]),
          Number(match[2]) - 1,
          Number(match[3])
        )
      );
    }

    function attendanceFormatDate(
      date
    ) {
      return date
        .toISOString()
        .slice(0,10);
    }

    function attendanceChunkRanges(
      startValue,
      endValue,
      chunkDays = 14
    ) {
      let start =
        attendanceParseDate(
          startValue
        );

      let end =
        attendanceParseDate(
          endValue
        );

      if(
        !start
        || !end
      ) {
        return [{
          start:
            startValue,
          end:
            endValue
        }];
      }

      if(start > end) {
        [start,end] =
          [end,start];
      }

      const ranges = [];
      let cursor =
        new Date(
          end.getTime()
        );

      while(
        cursor >= start
      ) {
        const chunkEnd =
          new Date(
            cursor.getTime()
          );

        let chunkStart =
          new Date(
            cursor.getTime()
          );

        chunkStart.setUTCDate(
          chunkStart.getUTCDate()
          - (
              Math.max(
                1,
                chunkDays
              )
              - 1
            )
        );

        if(
          chunkStart < start
        ) {
          chunkStart =
            new Date(
              start.getTime()
            );
        }

        ranges.push({
          start:
            attendanceFormatDate(
              chunkStart
            ),

          end:
            attendanceFormatDate(
              chunkEnd
            )
        });

        cursor =
          new Date(
            chunkStart.getTime()
          );

        cursor.setUTCDate(
          cursor.getUTCDate()
          - 1
        );
      }

      return ranges;
    }

    function attendanceIsTimeout(
      error
    ) {
      const message =
        String(
          error?.message
          || error
          || ""
        )
          .toLowerCase();

      return (
        message.includes(
          "statement timeout"
        )
        || message.includes(
          "canceling statement"
        )
      );
    }

    async function fetchAttendanceChunk(
      range,
      requestEmployeeCodes,
      statuses,
      depth = 0
    ) {
      const newArgs = {
        p_start_date:
          range.start,

        p_end_date:
          range.end,

        p_area:
          val("attZone")
          || null,

        p_sub_area:
          val("attSubArea")
          || null,

        p_department:
          val("attDepartment")
          || null,

        p_emp_codes:
          requestEmployeeCodes,

        p_attendance_statuses:
          null,

        p_schedule_statuses:
          null,

        p_limit:
          5000
      };

      let response =
        await state.client.rpc(
          "ta_get_attendance_detail_v61020",
          newArgs
        );

      let source =
        "V6.10.20";

      let serverStatusFilter =
        false;

      let serverSubAreaFilter =
        true;

      if(
        response.error
        && window.TimeClockShiftAPI
          ?.missingFunction?.(
            response.error
          )
      ) {
        const legacyArgs = {
          p_start_date:
            range.start,

          p_end_date:
            range.end,

          p_zone:
            val("attZone")
            || null,

          p_department:
            val("attDepartment")
            || null,

          p_emp_codes:
            requestEmployeeCodes,

          p_attendance_statuses:
            null,

          p_schedule_statuses:
            null,

          p_limit:
            5000
        };

        response =
          await state.client.rpc(
            "ta_get_attendance_detail_v664",
            legacyArgs
          );

        source =
          "V6.6.4";

        serverSubAreaFilter =
          false;
      }

      if(
        response.error
        && window.TimeClockShiftAPI
          ?.missingFunction?.(
            response.error
          )
      ) {
        response =
          await state.client.rpc(
            "ta_get_attendance_detail_v640",
            {
              p_start_date:
                range.start,

              p_end_date:
                range.end,

              p_zone:
                val("attZone")
                || null,

              p_department:
                val("attDepartment")
                || null,

              p_emp_codes:
                requestEmployeeCodes,

              p_attendance_statuses:
                null,

              p_schedule_statuses:
                null,

              p_limit:
                5000
            }
          );

        source =
          "V6.4.0";

        serverStatusFilter =
          false;

        serverSubAreaFilter =
          false;
      }

      if(
        response.error
        && window.TimeClockShiftAPI
          ?.missingFunction?.(
            response.error
          )
      ) {
        response =
          await state.client.rpc(
            "ta_get_attendance_detail_v619",
            {
              p_start_date:
                range.start,

              p_end_date:
                range.end,

              p_area:
                val("attZone")
                || null,

              p_sub_area:
                val("attSubArea")
                || null,

              p_department:
                val("attDepartment")
                || null,

              p_emp_codes:
                requestEmployeeCodes,

              p_attendance_statuses:
                null,

              p_schedule_statuses:
                null,

              p_limit:
                5000
            }
          );

        source =
          "V6.1.9";

        serverStatusFilter =
          false;

        serverSubAreaFilter =
          true;
      }

      if(
        response.error
        && attendanceIsTimeout(
          response.error
        )
        && depth < 4
      ) {
        const start =
          attendanceParseDate(
            range.start
          );

        const end =
          attendanceParseDate(
            range.end
          );

        const diffDays =
          start && end
            ? Math.floor(
                (
                  end.getTime()
                  - start.getTime()
                )
                / 86400000
              )
              + 1
            : 0;

        if(
          diffDays > 1
        ) {
          const half =
            Math.ceil(
              diffDays / 2
            );

          const newerStart =
            new Date(
              end.getTime()
            );

          newerStart.setUTCDate(
            newerStart.getUTCDate()
            - half
            + 1
          );

          const olderEnd =
            new Date(
              newerStart.getTime()
            );

          olderEnd.setUTCDate(
            olderEnd.getUTCDate()
            - 1
          );

          const newer =
            await fetchAttendanceChunk(
              {
                start:
                  attendanceFormatDate(
                    newerStart
                  ),

                end:
                  attendanceFormatDate(
                    end
                  )
              },
              requestEmployeeCodes,
              statuses,
              depth + 1
            );

          const older =
            olderEnd >= start
              ? await fetchAttendanceChunk(
                  {
                    start:
                      attendanceFormatDate(
                        start
                      ),

                    end:
                      attendanceFormatDate(
                        olderEnd
                      )
                  },
                  requestEmployeeCodes,
                  statuses,
                  depth + 1
                )
              : [];

          return [
            ...newer,
            ...older
          ];
        }
      }

      if(
        response.error
      ) {
        throw response.error;
      }

      let rows =
        Array.isArray(
          response.data
        )
          ? response.data
          : [];

      if(
        !serverSubAreaFilter
        && val("attSubArea")
      ) {
        const selected =
          val("attSubArea");

        rows =
          rows.filter(
            row =>
              String(
                row.sub_area
                || ""
              ) === selected
          );
      }

      rows =
        rows.map(row => {
          const enriched = {
            ...row
          };

          enriched.absence_minutes =
            attendanceAbsenceMinutes(
              enriched
            );

          enriched.display_status =
            attendanceDisplayStatus(
              enriched
            );

          if(
            !enriched.absence_reason
            && enriched.absence_minutes > 0
          ) {
            const hasIn =
              Boolean(
                enriched.actual_in_at
                || enriched.first_in
              );

            const hasOut =
              Boolean(
                enriched.actual_out_at
                || enriched.last_out
              );

            enriched.absence_reason =
              !hasIn && !hasOut
                ? "MISSING_BOTH"
                : !hasIn
                  ? "MISSING_IN"
                  : "MISSING_OUT";
          }

          enriched._attendance_source =
            source;

          return enriched;
        });

      // V6.11.20: status filtering is intentionally deferred until after
      // punch-meta enrichment. This prevents stale backend ABSENCE values from
      // excluding rows that actually have complete IN/OUT punches.

      return rows;
    }

    async function loadAttendance() {
      const requestId =
        ++attendanceLoadRequestId;

      showLoading(
        "กำลังค้นหารายละเอียดเวลา..."
      );

      try {
        const statuses =
          val("attStatus")
            ? [
                val(
                  "attStatus"
                )
              ]
            : null;

        const requestEmployeeCodes =
          attendanceEmployeeCodesForQuery();

        const ranges =
          attendanceChunkRanges(
            val("attStart"),
            val("attEnd"),
            14
          );

        const collected = [];

        for(
          let index = 0;
          index < ranges.length;
          index += 1
        ) {
          if(
            requestId
            !== attendanceLoadRequestId
          ) {
            return;
          }

          const rows =
            await fetchAttendanceChunk(
              ranges[index],
              requestEmployeeCodes,
              statuses
            );

          collected.push(
            ...rows
          );

          if(
            collected.length
            >= 5000
          ) {
            break;
          }
        }

        if(
          requestId
          !== attendanceLoadRequestId
        ) {
          return;
        }

        const unique =
          new Map();

        collected
          .sort(
            (a,b) =>
              String(
                b.work_date
                || ""
              )
                .localeCompare(
                  String(
                    a.work_date
                    || ""
                  )
                )
              || String(
                a.emp_code
                || ""
              )
                .localeCompare(
                  String(
                    b.emp_code
                    || ""
                  )
                )
          )
          .forEach(row => {
            const key =
              String(
                row.emp_code
                || ""
              )
              + "|"
              + String(
                row.work_date
                || ""
              )
                .slice(
                  0,
                  10
                );

            if(
              !unique.has(
                key
              )
            ) {
              unique.set(
                key,
                row
              );
            }
          });

        state.attendance =
          [...unique.values()]
            .slice(
              0,
              5000
            );

        await enrichAttendanceWorkSegmentsV6118(
          state.attendance,
          val("attStart"),
          val("attEnd")
        );

        state.attendance.forEach(
          normalizeAttendanceStatusFromPunchesV61120
        );

        if (val("attStatus")) {
          const wantedStatus = String(val("attStatus") || '').toUpperCase();
          state.attendance = state.attendance.filter(row => {
            const flags = attendancePolicyFlagsV61428(row);
            if (wantedStatus === 'ABSENCE') return flags.absence;
            if (wantedStatus === 'LATE') return flags.late;
            if (wantedStatus === 'EARLY_LEAVE') return flags.early;
            if (wantedStatus === 'LATE_AND_EARLY_LEAVE') return flags.late && flags.early;
            return flags.primaryStatus === wantedStatus;
          });
        }

        if(
          !attendanceEmployeeFilter.options
            .length
        ) {
          attendanceEmployeeFilter.options =
            fallbackAttendanceEmployeeOptions();

          state.filters.attendance.employees =
            attendanceEmployeeFilter.options;

          renderAttendanceEmployeeDropdown();
        }

        const activeEmployeeCodes =
          Array.isArray(
            requestEmployeeCodes
          )
            ? requestEmployeeCodes
            : null;

        const singleEmployeeCode =
          activeEmployeeCodes?.length
            === 1
              ? activeEmployeeCodes[0]
              : null;

        state.attendanceServerFilter =
          activeEmployeeCodes;

        renderAttendance();

        document.dispatchEvent(
          new CustomEvent(
            "timeclock:attendance-loaded",
            {
              detail: {
                count:
                  state.attendance.length,

                empCode:
                  singleEmployeeCode,

                empCodes:
                  activeEmployeeCodes,

                reachedLimit:
                  state.attendance.length
                    >= 5000
              }
            }
          )
        );

      } catch(error) {
        if(
          attendanceIsTimeout(
            error
          )
        ) {
          toast(
            "การค้นหายังใช้เวลานานเกินกำหนด กรุณาลองช่วงวันที่สั้นลง หรือเลือกพื้นที่/พนักงานเพิ่มเติม",
            "error"
          );
        } else {
          toast(
            humanError(
              error
            ),
            "error"
          );
        }
      } finally {
        hideLoading();
      }
    }

