  async function load(
    options={}
  ){
    const force =
      options?.force === true;

    if(
      state.loadRunning
    ){
      return;
    }

    state.loadRunning =
      true;

    state.lastLoadStartedAt =
      Date.now();

    fillYearOptions();

    renderLoadState(
      "กำลังโหลดข้อมูล..."
    );

    const ready =
      await waitForSystemPeriodReady(
        5000
      );

    if(!ready){
      renderLoadState(
        "Supabase Client ยังไม่พร้อม กรุณากด ลองใหม่",
        "error"
      );
      state.loadRunning = false;
      return;
    }

    if(!isHRAdmin()){
      renderLoadState(
        "บัญชีปัจจุบันไม่ใช่ HR Admin หรือ Profile ยังโหลดไม่สมบูรณ์",
        "error"
      );
      state.loadRunning = false;
      return;
    }

    const year =
      Number(
        $("systemPeriodYear")
          ?.value
      )
      || new Date()
        .getFullYear();

    app()?.showLoading?.(
      "กำลังโหลดรอบระบบ..."
    );

    let rows = null;
    let rpcError = null;

    try{
      rows =
        await withTimeout(
          rpc(
            "ta_list_system_periods_v6110",
            {
              p_year:
                year
            }
          ),
          8000,
          "SYSTEM_PERIOD_RPC_TIMEOUT"
        );

    }catch(error){
      rpcError =
        error;

      console.warn(
        "System Period RPC load failed; trying direct-table fallback:",
        error
      );

      try{
        rows =
          await loadSystemPeriodsDirect(
            year
          );

        app()?.toast?.(
          "โหลดรอบระบบผ่านโหมดสำรองแล้ว",
          "warning"
        );

      }catch(fallbackError){
        console.error(
          "System Period fallback load failed:",
          fallbackError
        );

        const message =
          app()?.humanError?.(
            fallbackError
          )
          || fallbackError?.message
          || app()?.humanError?.(
            rpcError
          )
          || rpcError?.message
          || "ไม่สามารถโหลดข้อมูลได้";

        renderLoadState(
          message,
          "error"
        );

        app()?.toast?.(
          message,
          "error"
        );

        state.loadRunning = false;
        return;
      }
    }finally{
      app()?.hideLoading?.();
    }

    state.rows =
      Array.isArray(rows)
        ? rows
        : [];

    fillYearOptions();
    renderSummary();
    applyFilter();

    if(
      !state.rows.length
    ){
      renderTable();
    }

    state.lastLoadCompletedAt =
      Date.now();

    if(
      $("systemPeriodPageLoadMeta")
    ){
      $("systemPeriodPageLoadMeta")
        .textContent =
        state.rows.length
          ? `โหลดแล้ว ${state.rows.length.toLocaleString("th-TH")} รอบ`
          : "โหลดแล้ว • ยังไม่มีรอบระบบในปีที่เลือก";

      $("systemPeriodPageLoadMeta")
        .classList.remove(
          "is-error",
          "is-loading"
        );
    }

    state.loadRunning =
      false;
  }

  function setModalOpen(
    open
  ){
    const modal =
      $("systemPeriodModal");

    if(!modal){
      console.error(
        "V6.11.15: systemPeriodModal not found"
      );

      app()?.toast?.(
        "ไม่พบหน้าต่างเพิ่มรอบระบบ กรุณารีเฟรชไฟล์หน้าเว็บ V6.11.15",
        "error"
      );

      return false;
    }

    modal.classList.toggle(
      "hidden",
      !open
    );

    modal.setAttribute(
      "aria-hidden",
      open
        ? "false"
        : "true"
    );

    if(open){
      modal.style.display =
        "grid";

      document.body
        ?.classList.add(
          "system-period-modal-open"
        );

      requestAnimationFrame(
        () => {
          $("systemPeriodMonthInput")
            ?.focus?.();
        }
      );

      document.dispatchEvent(
        new CustomEvent(
          "timeclock:system-period-modal-opened"
        )
      );

    }else{
      modal.style.display =
        "";

      document.body
        ?.classList.remove(
          "system-period-modal-open"
        );
    }

    return true;
  }

  function updateRangePreview(){
    const key=
      $("systemPeriodMonthInput")
        ?.value;

    if(!key){
      $("systemPeriodRangePreview")
        .textContent="-";
      return;
    }

    $("systemPeriodRangePreview")
      .textContent=
      `${formatDate(
        `${key}-01`
      )} – ${formatDate(
        monthEnd(key)
      )}`;
  }

  function openNew(){
    state.currentEdit=null;

    const title =
      $("systemPeriodModalTitle");

    const monthInput =
      $("systemPeriodMonthInput");

    const scheduleDeadlineInput =
      $("systemPeriodScheduleDeadlineInput");

    const certDeadlineInput =
      $("systemPeriodCertDeadlineInput");

    const scheduleOpenInput =
      $("systemPeriodScheduleOpen");

    const certOpenInput =
      $("systemPeriodCertOpen");

    const noteInput =
      $("systemPeriodNote");

    if(
      !title
      || !monthInput
      || !scheduleDeadlineInput
      || !certDeadlineInput
      || !scheduleOpenInput
      || !certOpenInput
      || !noteInput
    ){
      console.error(
        "V6.11.15: System Period modal fields incomplete"
      );

      app()?.toast?.(
        "องค์ประกอบหน้าต่างเพิ่มรอบระบบไม่ครบ กรุณา Deploy V6.11.15 ใหม่ทั้งหมด",
        "error"
      );

      return;
    }

    title.textContent=
      "เพิ่มรอบระบบ";

    const now=new Date();
    const key=[
      now.getFullYear(),
      String(
        now.getMonth()+1
      ).padStart(2,"0")
    ].join("-");

    monthInput.disabled=false;
    monthInput.value=key;

    const end=monthEnd(key);

    scheduleDeadlineInput.value=
      addDays(
        end,
        10
      );

    certDeadlineInput.value=
      addDays(
        end,
        10
      );

    scheduleOpenInput.checked=true;
    certOpenInput.checked=true;
    noteInput.value="";

    updateRangePreview();
    setModalOpen(true);
  }

  function openEdit(
    month
  ){
    const row=
      state.rows.find(
        item =>
          monthKey(
            item.period_month
          )===
          monthKey(month)
      );

    if(!row) return;

    state.currentEdit=row;

    $("systemPeriodModalTitle")
      .textContent=
      `แก้ไขรอบ ${monthLabel(
        row.period_month
      )}`;

    $("systemPeriodMonthInput")
      .disabled=true;

    $("systemPeriodMonthInput")
      .value=
      monthKey(
        row.period_month
      );

    $("systemPeriodScheduleDeadlineInput")
      .value=
      String(
        row.schedule_edit_deadline
        || ""
      ).slice(0,10);

    $("systemPeriodCertDeadlineInput")
      .value=
      String(
        row.attendance_certify_deadline
        || ""
      ).slice(0,10);

    $("systemPeriodScheduleOpen")
      .checked=
      !!row.schedule_open;

    $("systemPeriodCertOpen")
      .checked=
      !!row.certification_open;

    $("systemPeriodNote")
      .value=
      row.note || "";

    updateRangePreview();
    setModalOpen(true);
  }

  async function save(){
    const key=
      $("systemPeriodMonthInput")
        ?.value;

    const scheduleDeadline=
      $("systemPeriodScheduleDeadlineInput")
        ?.value;

    const certDeadline=
      $("systemPeriodCertDeadlineInput")
        ?.value;

    if(
      !key
      || !scheduleDeadline
      || !certDeadline
    ){
      return app()?.toast?.(
        "กรุณากรอกเดือนและ Deadline ให้ครบ",
        "error"
      );
    }

    const button=$(
      "systemPeriodSaveBtn"
    );

    if(button){
      button.disabled=true;
      button.textContent=
        "กำลังบันทึก...";
    }

    try{
      await rpc(
        "ta_upsert_system_period_v6110",
        {
          p_period_month:
            `${key}-01`,
          p_schedule_edit_deadline:
            scheduleDeadline,
          p_attendance_certify_deadline:
            certDeadline,
          p_schedule_open:
            $("systemPeriodScheduleOpen")
              ?.checked
            ?? true,
          p_certification_open:
            $("systemPeriodCertOpen")
              ?.checked
            ?? true,
          p_note:
            $("systemPeriodNote")
              ?.value
              ?.trim()
            || null
        }
      );

      state.periodCache.clear();
      setModalOpen(false);

      app()?.toast?.(
        `บันทึกรอบ ${monthLabel(
          `${key}-01`
        )} เรียบร้อย`,
        "success"
      );

      await load();

    }catch(error){
      app()?.toast?.(
        app()?.humanError?.(
          error
        )
        || error.message,
        "error"
      );
    }finally{
      if(button){
        button.disabled=false;
        button.textContent=
          "บันทึกรอบระบบ";
      }
    }
  }

  async function togglePeriod(
    month,
    action,
    currentOpen
  ){
    const next=
      !currentOpen;

    const label=
      action==="SCHEDULE"
        ? "การจัดกะ"
        : "การรับรองเวลา";

    if(
      !await window.tcConfirm(
        `${next?"เปิด":"ปิด"}${label} สำหรับรอบ ${monthLabel(
          month
        )}?`
      )
    ){
      return;
    }

    try{
      await rpc(
        "ta_set_system_period_switch_v6110",
        {
          p_period_month:
            monthStart(month),
          p_action:
            action,
          p_open:
            next,
          p_note:
            `${next?"เปิด":"ปิด"}${label}จากหน้าจัดการรอบระบบ`
        }
      );

      state.periodCache.clear();

      app()?.toast?.(
        `${next?"เปิด":"ปิด"}${label}เรียบร้อย`,
        "success"
      );

      await load();

    }catch(error){
      app()?.toast?.(
        app()?.humanError?.(
          error
        )
        || error.message,
        "error"
      );
    }
  }

